<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue';
import { NAlert, NButton, NCheckbox, NCollapse, NCollapseItem, NForm, NFormItem, NInputNumber, NModal, NSelect, NTag } from 'naive-ui';
import type { CallRecord, Project, ProviderSummary, Reservation, Shot } from '../types.ts';
const props = defineProps<{ show: boolean; project: Project; shots: Shot[]; boardRevision: number; providers: ProviderSummary[]; calls: CallRecord[]; disabled: boolean }>();
const emit = defineEmits<{ 'update:show': [value: boolean]; submit: [input: { providerId: string; reservation: Reservation; clientRequestId: string }]; settings: [] }>();
const providerId = ref<string | null>(null);
const acknowledged = ref(false);
const independentAcknowledged = ref(false);
const operationId = ref('');
const reservation = reactive<Reservation>({ currency: 'USD', amount: 0.1, singleLimit: 1, projectLimit: 5 });
const options = computed(() => props.providers.filter(provider => provider.kind === 'chat-completions').map(provider => ({ value: provider.id, label: `${provider.label} · ${provider.model}` })));
const provider = computed(() => props.providers.find(item => item.id === providerId.value));
const unresolved = computed(() => props.calls.filter(call => call.status === 'submission_unknown' && call.actualAmount === null));
const used = computed(() => props.calls.filter(call => call.currency === reservation.currency).reduce((sum, call) => sum + (call.actualAmount ?? call.reservedAmount), 0));
const valid = computed(() => Boolean(provider.value && props.project.brief.trim() && acknowledged.value && (!unresolved.value.length || independentAcknowledged.value) && [reservation.amount, reservation.singleLimit, reservation.projectLimit].every(value => Number.isFinite(value) && value >= 0) && reservation.singleLimit >= reservation.amount && reservation.projectLimit >= used.value + reservation.amount));
watch(() => props.show, show => { if (show) { acknowledged.value = false; independentAcknowledged.value = false; operationId.value = crypto.randomUUID(); if (!options.value.some(option => option.value === providerId.value)) providerId.value = options.value[0]?.value || null; } });
watch(() => [props.boardRevision, props.project.revision, providerId.value, reservation.currency, reservation.amount, reservation.singleLimit, reservation.projectLimit], () => { acknowledged.value = false; independentAcknowledged.value = false; operationId.value = crypto.randomUUID(); });
function submit() { if (providerId.value && valid.value && !props.disabled) emit('submit', { providerId: providerId.value, reservation: { ...reservation }, clientRequestId: operationId.value }); }
</script>

<template>
  <NModal :show="show" preset="card" title="审阅这次推理请求" class="reasoning-modal" :mask-closable="!disabled" :closable="!disabled" @update:show="emit('update:show', $event)"><p class="dialog-intro">让模型基于创作简报和当前分镜提出修改草稿。最多发送一次请求，项目内容由你审阅后再应用。</p><NForm @submit.prevent="submit"><NFormItem label="推理连接"><NSelect v-model:value="providerId" :options="options" :disabled="disabled" placeholder="选择已保存的推理连接" /></NFormItem><NAlert v-if="!options.length" type="info" :show-icon="false" class="draft-alert">还没有推理连接。<NButton text type="primary" @click="emit('settings')">去设置连接</NButton></NAlert><div v-if="provider" class="reasoning-target"><div class="heading-line"><strong>{{ provider.model }}</strong><NTag size="small" :bordered="false">尚未验证</NTag></div><code>{{ provider.baseUrl }}</code><p>{{ provider.timeoutMs / 1000 }} 秒超时 · 最多 {{ provider.maxOutputTokens }} 输出 tokens · 单次请求</p></div><NCollapse class="reasoning-context"><NCollapseItem title="查看将发送的简报与分镜" name="context"><div class="context-brief"><strong>创作简报</strong><p>{{ project.brief || '（简报为空）' }}</p></div><div v-if="!shots.length" class="context-shot">当前没有镜头，模型可提出新分镜。</div><article v-for="(shot, index) in shots" :key="shot.id" class="context-shot"><h3>{{ String(index + 1).padStart(2, '0') }} · {{ shot.title }}</h3><dl><div><dt>目的</dt><dd>{{ shot.purpose || '（留空）' }}</dd></div><div><dt>画面</dt><dd>{{ shot.description || '（留空）' }}</dd></div><div><dt>动作</dt><dd>{{ shot.action || '（留空）' }}</dd></div><div><dt>时长 / 素材方式</dt><dd>{{ shot.durationMs / 1000 }} 秒 · {{ shot.mode }}</dd></div><div><dt>字幕</dt><dd>{{ shot.caption || '（留空）' }}</dd></div><div><dt>参考素材 ID</dt><dd>{{ shot.referenceArtifactIds.join('、') || '无' }}</dd></div></dl></article><p class="panel-footnote">分镜版本 r{{ boardRevision }}。请求包含镜头字段与版本标识，不上传本地媒体文件。</p></NCollapseItem></NCollapse><h3 class="reservation-title">本地费用预留</h3><div class="reservation-fields"><NFormItem label="币种"><NSelect v-model:value="reservation.currency" :options="[{ label: 'USD', value: 'USD' }, { label: 'CNY', value: 'CNY' }]" :disabled="disabled" /></NFormItem><NFormItem label="本次预留"><NInputNumber v-model:value="reservation.amount" :min="0" :precision="4" :step="0.1" :disabled="disabled" /></NFormItem><NFormItem label="单次上限"><NInputNumber v-model:value="reservation.singleLimit" :min="0" :precision="4" :step="1" :disabled="disabled" /></NFormItem><NFormItem label="项目上限"><NInputNumber v-model:value="reservation.projectLimit" :min="0" :precision="4" :step="1" :disabled="disabled" /></NFormItem></div><p class="form-note">当前项目已记录或仍预留 {{ used.toFixed(4) }} {{ reservation.currency }}。金额由你填写，用于本地限额校验；不是供应商的价格或账单保证。本地免费模型可填写 0。</p><NAlert v-if="reservation.amount > reservation.singleLimit || used + reservation.amount > reservation.projectLimit" type="warning" :show-icon="false" class="draft-alert">本次预留超过单次或项目上限，请调整后再提交。</NAlert><NAlert v-if="unresolved.length" type="warning" :show-icon="false" class="draft-alert">有响应不明的调用尚待核对，其预留金额继续计入项目用量。下面提交的是一次独立新请求，不会恢复或重发旧调用；未知账单可以继续保留待核对状态。</NAlert><NCheckbox v-if="unresolved.length" v-model:checked="independentAcknowledged" class="reasoning-acknowledgement" :disabled="disabled">我确认发起独立新请求，旧调用继续保留预留并等待核对。</NCheckbox><NCheckbox v-model:checked="acknowledged" class="reasoning-acknowledgement" :disabled="disabled || !provider">我已核对发送内容、连接和本地费用预留。</NCheckbox><div class="dialog-actions"><NButton :disabled="disabled" @click="emit('update:show', false)">返回编辑</NButton><NButton type="primary" attr-type="submit" :loading="disabled" :disabled="disabled || !valid">提交一次请求</NButton></div></NForm></NModal>
</template>
